int search_ldap_user(const char* username, const char* domain) {
    LDAP* ld = NULL;
    LDAPMessage* result = NULL;
    LDAPMessage* entry = NULL;
    int rc;
    char* base_dn = NULL;
    char filter[512];

    if (!username || !domain) {
