    snprintf(filter, sizeof(filter), "(uid=%s)", username);

    rc = ldap_initialize(&ld, "ldap://localhost");
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "ldap_initialize failed: %s\n", ldap_err2string(rc));
        free(base_dn);
        return 1;
    }

    rc = ldap_simple_bind_s(ld, NULL, NULL);
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "Bind failed: %s\n", ldap_err2string(rc));
        ldap_unbind_s(ld);
        free(base_dn);
        return 1;
    }

    char* attrs[] = { "cn", "uid", "mail", "telephoneNumber", "dn", NULL };

    rc = ldap_search_s(ld, base_dn, LDAP_SCOPE_SUBTREE, filter, attrs, 0, &result);
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "Search failed: %s\n", ldap_err2string(rc));
        ldap_unbind_s(ld);
        free(base_dn);
        return 1;
    }

    int count = ldap_count_entries(ld, result);
    if (count <= 0) {
        printf("No user found for uid=%s in %s\n", username, base_dn);
    } else {
        printf("Found %d entries:\n", count);
        entry = ldap_first_entry(ld, result);
        while (entry != NULL) {
            char* dn = ldap_get_dn(ld, entry);
            printf("DN: %s\n", dn ? dn : "(null)");
            if (dn) ldap_memfree(dn);

            BerElement* ber = NULL;
            char* attr = ldap_first_attribute(ld, entry, &ber);
            while (attr != NULL) {
                char** vals = ldap_get_values(ld, entry, attr);
                if (vals != NULL) {
